const body = $input.all()[0].json.body;
const query = body.query || 'Привет';
const ctx = body.context || {};
const goals = ctx.goals || {};
const consumed = ctx.consumed_today || {};
const meals = ctx.today_meals || [];

const goalsCalories = goals.calories || 'неизвестно';
const goalsProteins = goals.proteins || 'неизвестно';
const goalsFats = goals.fats || 'неизвестно';
const goalsCarbs = goals.carbs || 'неизвестно';

const consumedCalories = consumed.calories || 0;
const consumedProteins = consumed.proteins || 0;
const consumedFats = consumed.fats || 0;
const consumedCarbs = consumed.carbs || 0;

const mealsStr = meals.length > 0 ? JSON.stringify(meals) : 'пусто (пользователь ещё ничего не записал)';

const prompt = `Ты - нутрициолог-ассистент приложения FRUktik.

Запрос пользователя: ${query}

Данные дневника пользователя на сегодня (получены автоматически из приложения):
- Цель КБЖУ: ${goalsCalories} ккал, Б: ${goalsProteins} г, Ж: ${goalsFats} г, У: ${goalsCarbs} г
- Уже съедено: ${consumedCalories} ккал, Б: ${consumedProteins} г, Ж: ${consumedFats} г, У: ${consumedCarbs} г
- Список съеденного: ${mealsStr}

СТРОГИЕ ПРАВИЛА:
1. Отвечай ТОЛЬКО на русском, кратко и по делу.
2. Данные дневника уже предоставлены выше — НИКОГДА не проси пользователя что-то прислать, написать или рассказать про свое питание. Ты УЖЕ все знаешь.
3. Если дневник пуст, мягко напомни записать приём пищи.
4. НЕ здоровайся. НЕ представляйся. Сразу отвечай по существу вопроса.
5. Пиши простым текстом без markdown, без звёздочек, без решёток.`;

return [{ json: { prompt } }];

const items = $input.all();
try {
  const response = items[0].json;
  const text = response.content.parts[0].text;
  return [{ json: { reply: text, success: true } }];
} catch (e) {
  return [{ json: { reply: 'Ошибка при обработке ответа ИИ: ' + e.message, success: false } }];
}

for (const item of $input.all()) {
  const base64Str = item.json.body.image_base64;
  if (base64Str) {
    item.binary = {
      data: {
        data: base64Str,
        mimeType: item.json.body.mime_type || 'image/jpeg',
        fileName: 'image.jpg'
      }
    };
  }
}
return $input.all();

const items = $input.all();
try {
  const text = items[0].json.content.parts[0].text;
  const jsonStrMatch = text.match(/\[[\s\S]*\]/);
  const jsonStr = jsonStrMatch ? jsonStrMatch[0] : text;
  const parsed = JSON.parse(jsonStr);
  return parsed.map(item => ({ json: item }));
} catch (e) {
  return [{ json: { error: 'Failed to parse JSON' } }];
}
